import { Pool } from "pg";

export interface ShardConfig {
  id: number;
  connectionString: string;
}

export function hashKey(key: string): number {
  let h = 0;
  for (let i = 0; i < key.length; i++) {
    h = (h << 5) - h + key.charCodeAt(i);
    h |= 0;
  }
  return h;
}

export class ShardRouter {
  private readonly pools: Pool[];

  constructor(shards: ShardConfig[]) {
    if (shards.length === 0) throw new Error("at least one shard is required");
    this.pools = [...shards]
      .sort((a, b) => a.id - b.id)
      .map((s) => new Pool({ connectionString: s.connectionString, max: 10 }));
  }

  get shardCount(): number {
    return this.pools.length;
  }

  shardFor(restaurantId: string): number {
    return hashKey(restaurantId) % this.pools.length;
  }

  poolFor(restaurantId: string): Pool {
    return this.pools[this.shardFor(restaurantId)];
  }

  all(): Pool[] {
    return this.pools;
  }

  async close(): Promise<void> {
    await Promise.all(this.pools.map((p) => p.end()));
  }
}

import { ShardRouter } from "./shardRouter";

export interface OrderRow {
  id: string;
  restaurant_id: string;
  customer_id: string;
  status: string;
  total_cents: number;
  created_at: Date;
}

export class OrderRepository {
  constructor(private readonly router: ShardRouter) {}

  async create(order: Omit<OrderRow, "created_at">): Promise<void> {
    await this.router.poolFor(order.restaurant_id).query(
      `INSERT INTO orders (id, restaurant_id, customer_id, status, total_cents)
       VALUES ($1, $2, $3, $4, $5)`,
      [order.id, order.restaurant_id, order.customer_id, order.status, order.total_cents],
    );
  }

  async activeForRestaurant(restaurantId: string): Promise<OrderRow[]> {
    const { rows } = await this.router.poolFor(restaurantId).query<OrderRow>(
      `SELECT * FROM orders
       WHERE restaurant_id = $1 AND status IN ('placed', 'preparing', 'ready')
       ORDER BY created_at`,
      [restaurantId],
    );
    return rows;
  }

  async recentForCustomer(customerId: string, limit = 20): Promise<OrderRow[]> {
    const perShard = await Promise.all(
      this.router.all().map((pool) =>
        pool
          .query<OrderRow>(
            `SELECT * FROM orders WHERE customer_id = $1 ORDER BY created_at DESC LIMIT $2`,
            [customerId, limit],
          )
          .then((r) => r.rows),
      ),
    );
    return perShard
      .flat()
      .sort((a, b) => b.created_at.getTime() - a.created_at.getTime())
      .slice(0, limit);
  }
}
